CREATE PROCEDURE core.sp_activar_auditoria_esquema
    @schema_name SYSNAME
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @tabla SYSNAME, @pk SYSNAME, @sql NVARCHAR(MAX);

    DECLARE c CURSOR LOCAL FAST_FORWARD FOR
        SELECT t.name FROM sys.tables t
        JOIN sys.schemas s ON s.schema_id = t.schema_id
        WHERE s.name = @schema_name AND t.name <> 'auditoria_logs';

    OPEN c;
    FETCH NEXT FROM c INTO @tabla;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF OBJECT_ID(@schema_name + '.trg_audit_' + @tabla) IS NULL
        BEGIN
            SELECT @pk = c.name
            FROM sys.indexes i
            JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id
            JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
            WHERE i.object_id = OBJECT_ID(@schema_name + '.' + @tabla)
              AND i.is_primary_key = 1 AND ic.key_ordinal = 1;
            SET @pk = ISNULL(@pk, 'id');

            SET @sql = REPLACE(REPLACE(REPLACE(N'
BEGIN
    SET NOCOUNT ON;
    DECLARE @ip NVARCHAR(45) = (SELECT CAST(client_net_address AS NVARCHAR(45))
                                FROM sys.dm_exec_connections
                                WHERE session_id = @@SPID);

    IF EXISTS (SELECT 1 FROM inserted) AND NOT EXISTS (SELECT 1 FROM deleted)
        INSERT INTO core.auditoria_logs (db_user, modulo, entidad, accion, registro_id, datos_anteriores, datos_nuevos, campos_modificados, ip_origen)
        SELECT SYSTEM_USER, ''{{ESQ}}'', ''{{TAB}}'', ''INSERT'',
               JSON_VALUE((SELECT * FROM inserted FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), ''$.{{PK}}''),
               NULL, (SELECT * FROM inserted FOR JSON PATH), NULL, @ip;

    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
        INSERT INTO core.auditoria_logs (db_user, modulo, entidad, accion, registro_id, datos_anteriores, datos_nuevos, campos_modificados, ip_origen)
        SELECT SYSTEM_USER, ''{{ESQ}}'', ''{{TAB}}'', ''UPDATE'',
               JSON_VALUE((SELECT * FROM inserted FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), ''$.{{PK}}''),
               (SELECT * FROM deleted FOR JSON PATH), (SELECT * FROM inserted FOR JSON PATH), NULL, @ip;

    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
        INSERT INTO core.auditoria_logs (db_user, modulo, entidad, accion, registro_id, datos_anteriores, datos_nuevos, campos_modificados, ip_origen)
        SELECT SYSTEM_USER, ''{{ESQ}}'', ''{{TAB}}'', ''DELETE'',
               JSON_VALUE((SELECT * FROM deleted FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), ''$.{{PK}}''),
               (SELECT * FROM deleted FOR JSON PATH), NULL, NULL, @ip;
END
', '{{ESQ}}', @schema_name), '{{TAB}}', @tabla), '{{PK}}', @pk);
            EXEC sp_executesql @sql;
        END
        FETCH NEXT FROM c INTO @tabla;
    END
    CLOSE c; DEALLOCATE c;
END;
GO



CREATE TRIGGER core.trg_audit_administrativos
ON core.administrativos
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ip NVARCHAR(45) = (SELECT CAST(client_net_address AS NVARCHAR(45))
                                FROM sys.dm_exec_connections
                                WHERE session_id = @@SPID);

    IF EXISTS (SELECT 1 FROM inserted) AND NOT EXISTS (SELECT 1 FROM deleted)
        INSERT INTO core.auditoria_logs (db_user, modulo, entidad, accion, registro_id, datos_anteriores, datos_nuevos, campos_modificados, ip_origen)
        SELECT SYSTEM_USER, 'core', 'administrativos', 'INSERT',
               JSON_VALUE((SELECT * FROM inserted FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), '$.id'),
               NULL, (SELECT * FROM inserted FOR JSON PATH), NULL, @ip;

    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
        INSERT INTO core.auditoria_logs (db_user, modulo, entidad, accion, registro_id, datos_anteriores, datos_nuevos, campos_modificados, ip_origen)
        SELECT SYSTEM_USER, 'core', 'administrativos', 'UPDATE',
               JSON_VALUE((SELECT * FROM inserted FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), '$.id'),
               (SELECT * FROM deleted FOR JSON PATH), (SELECT * FROM inserted FOR JSON PATH), NULL, @ip;

    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
        INSERT INTO core.auditoria_logs (db_user, modulo, entidad, accion, registro_id, datos_anteriores, datos_nuevos, campos_modificados, ip_origen)
        SELECT SYSTEM_USER, 'core', 'administrativos', 'DELETE',
               JSON_VALUE((SELECT * FROM deleted FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), '$.id'),
               (SELECT * FROM deleted FOR JSON PATH), NULL, NULL, @ip;
END
GO

