CREATE TRIGGER mod06.trg_titular_al_egresar
ON mod06.egresos
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE e SET e.condicion = 'Titulado'
    FROM core.estudiantes e
    JOIN inserted i ON e.id = i.estudiante_id
    WHERE e.condicion <> 'Titulado';
END;
GO

CREATE TRIGGER mod05.trg_cita_before
ON mod05.citas_psicologia
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE c SET c.persona_id = u.persona_id
    FROM mod05.citas_psicologia c
    JOIN inserted i ON c.id = i.id
    JOIN core.usuarios u ON LOWER(u.email) = LOWER(i.email)
    WHERE i.persona_id IS NULL;
END;
GO

CREATE TRIGGER mod05.trg_incidencia_before
ON mod05.incidencias
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @es_insert BIT = CASE WHEN NOT EXISTS (SELECT 1 FROM deleted) THEN 1 ELSE 0 END;

    IF @es_insert = 1
    BEGIN
        UPDATE i SET
            i.bien_id             = COALESCE(i.bien_id, r.bien_id),
            i.aula_id             = COALESCE(i.aula_id, r.aula_id),
            i.carrera_id          = COALESCE(i.carrera_id, r.carrera_id),
            i.unidad_didactica_id = COALESCE(i.unidad_didactica_id, r.unidad_didactica_id),
            i.docente_id          = COALESCE(i.docente_id, r.docente_id),
            i.tipo_falla          = COALESCE(i.tipo_falla, r.tipo_falla),
            i.descripcion         = COALESCE(i.descripcion, r.descripcion)
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        JOIN mod05.reportes_incidencia r ON r.id = ins.reporte_id
        WHERE ins.reporte_id IS NOT NULL;

        UPDATE i SET i.ambiente_id = ax.id_ambiente
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        CROSS APPLY (
            SELECT TOP 1 a.id_ambiente
            FROM mod03.asignacion a
            WHERE a.id_bien = i.bien_id AND a.estado = 'Activa'
            ORDER BY a.fecha_asignacion DESC, a.id_asignacion DESC
        ) ax
        WHERE i.ambiente_id IS NULL AND i.bien_id IS NOT NULL;

        UPDATE i SET i.estado_bien_previo = b.estado
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        JOIN mod03.bien b ON b.id_bien = i.bien_id;

        UPDATE i SET i.fecha_cierre = GETDATE()
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        WHERE i.estado IN ('Reparado', 'Baja Definitiva', 'Descartada')
          AND i.fecha_cierre IS NULL;
    END
    ELSE
    BEGIN
        UPDATE i SET
            i.bien_id             = COALESCE(i.bien_id, r.bien_id),
            i.aula_id             = COALESCE(i.aula_id, r.aula_id),
            i.carrera_id          = COALESCE(i.carrera_id, r.carrera_id),
            i.unidad_didactica_id = COALESCE(i.unidad_didactica_id, r.unidad_didactica_id),
            i.docente_id          = COALESCE(i.docente_id, r.docente_id),
            i.tipo_falla          = COALESCE(i.tipo_falla, r.tipo_falla),
            i.descripcion         = COALESCE(i.descripcion, r.descripcion)
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        JOIN mod05.reportes_incidencia r ON r.id = ins.reporte_id
        WHERE ins.reporte_id IS NOT NULL;

        UPDATE i SET i.ambiente_id = ax.id_ambiente
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        CROSS APPLY (
            SELECT TOP 1 a.id_ambiente
            FROM mod03.asignacion a
            WHERE a.id_bien = i.bien_id AND a.estado = 'Activa'
            ORDER BY a.fecha_asignacion DESC, a.id_asignacion DESC
        ) ax
        WHERE i.ambiente_id IS NULL AND i.bien_id IS NOT NULL;

        UPDATE i SET i.estado_bien_previo = b.estado
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        JOIN mod03.bien b ON b.id_bien = i.bien_id;

        UPDATE i SET i.fecha_cierre = GETDATE()
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        WHERE i.estado IN ('Reparado', 'Baja Definitiva', 'Descartada')
          AND i.fecha_cierre IS NULL;

        UPDATE i SET i.fecha_cierre = NULL
        FROM mod05.incidencias i
        JOIN inserted ins ON i.id = ins.id
        JOIN deleted de ON de.id = ins.id
        WHERE de.fecha_cierre IS NOT NULL
          AND de.estado IN ('Reparado', 'Baja Definitiva', 'Descartada')
          AND i.estado NOT IN ('Reparado', 'Baja Definitiva', 'Descartada');
    END
END;
GO

CREATE TRIGGER mod05.trg_incidencia_after
ON mod05.incidencias
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE r SET
        r.estado = 'Convertido',
        r.revisado_por = COALESCE(r.revisado_por, i.registrada_por),
        r.fecha_revision = COALESCE(r.fecha_revision, GETDATE())
    FROM mod05.reportes_incidencia r
    JOIN inserted i ON r.id = i.reporte_id
    WHERE i.reporte_id IS NOT NULL AND r.estado <> 'Convertido';
END;
GO

CREATE TRIGGER mod05.trg_reporte_before
ON mod05.reportes_incidencia
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE r SET r.docente_id = d.id
    FROM mod05.reportes_incidencia r
    JOIN inserted i ON r.id = i.id
    JOIN core.usuarios u ON u.id = i.reportado_por
    JOIN core.docentes d ON d.persona_id = u.persona_id
    WHERE i.docente_id IS NULL;

    UPDATE r SET
        r.aula_id             = COALESCE(r.aula_id, cd.aula_id),
        r.carrera_id          = COALESCE(r.carrera_id, cd.carrera_id),
        r.unidad_didactica_id = COALESCE(r.unidad_didactica_id, cd.unidad_didactica_id),
        r.periodo_id          = COALESCE(r.periodo_id, cd.periodo_id),
        r.docente_id          = COALESCE(r.docente_id, cd.docente_id)
    FROM mod05.reportes_incidencia r
    JOIN inserted i ON r.id = i.id
    JOIN mod02.clases_docente cd ON cd.id = i.clase_docente_id
    WHERE i.clase_docente_id IS NOT NULL;

    UPDATE r SET r.periodo_id = pa.id
    FROM mod05.reportes_incidencia r
    JOIN inserted i ON r.id = i.id
    CROSS APPLY (
        SELECT TOP 1 p.id FROM core.periodos_academicos p
        WHERE p.es_activo = 1 ORDER BY p.id DESC
    ) pa
    WHERE i.periodo_id IS NULL AND r.periodo_id IS NULL;
END;
GO

CREATE TRIGGER mod05.trg_sync_estado_bien
ON mod05.incidencias
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @es_insert BIT = CASE WHEN NOT EXISTS (SELECT 1 FROM deleted) THEN 1 ELSE 0 END;

    IF @es_insert = 1
    BEGIN
        UPDATE b SET b.estado =
            CASE i.estado
                WHEN 'Abierta'               THEN 'Inoperativo'
                WHEN 'En diagnóstico'        THEN 'En reparación'
                WHEN 'En espera de repuesto' THEN 'En reparación'
                WHEN 'Reparado'              THEN 'Bueno'
                WHEN 'Baja Definitiva'       THEN 'Baja en trámite'
                WHEN 'Descartada'            THEN COALESCE(i.estado_bien_previo, 'Bueno')
            END
        FROM mod03.bien b
        JOIN inserted i ON b.id_bien = i.bien_id
        WHERE i.dictamen = 'Dañado' AND b.id_bien IS NOT NULL;
    END
    ELSE
    BEGIN
        UPDATE b SET b.estado =
            CASE i.estado
                WHEN 'Abierta'               THEN 'Inoperativo'
                WHEN 'En diagnóstico'        THEN 'En reparación'
                WHEN 'En espera de repuesto' THEN 'En reparación'
                WHEN 'Reparado'              THEN 'Bueno'
                WHEN 'Baja Definitiva'       THEN 'Baja en trámite'
                WHEN 'Descartada'            THEN COALESCE(i.estado_bien_previo, 'Bueno')
            END
        FROM mod03.bien b
        JOIN inserted i ON b.id_bien = i.bien_id
        WHERE i.dictamen = 'Dañado' AND b.id_bien IS NOT NULL;

        UPDATE b SET b.estado = COALESCE(i.estado_bien_previo, 'Bueno')
        FROM mod03.bien b
        JOIN inserted i ON b.id_bien = i.bien_id
        JOIN deleted de ON de.id = i.id
        WHERE i.dictamen <> 'Dañado' AND de.dictamen = 'Dañado';
    END
END;
GO

CREATE TRIGGER mod08.trg_sync_roles
ON mod08.asignaciones_rol
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE ur SET ur.es_activo = 1, ur.asignado_en = i.asignado_en
    FROM core.usuario_roles ur
    JOIN inserted i ON ur.usuario_id = i.usuario_id AND ur.rol_id = i.rol_id;

    INSERT INTO core.usuario_roles (usuario_id, rol_id, asignado_en, es_activo)
    SELECT i.usuario_id, i.rol_id, i.asignado_en, 1
    FROM inserted i
    WHERE NOT EXISTS (
        SELECT 1 FROM core.usuario_roles ur
        WHERE ur.usuario_id = i.usuario_id AND ur.rol_id = i.rol_id);

    UPDATE ur SET ur.es_activo = 0
    FROM core.usuario_roles ur
    JOIN inserted i ON ur.usuario_id = i.usuario_id AND ur.rol_id = i.rol_id
    JOIN deleted de ON de.usuario_id = i.usuario_id AND de.rol_id = i.rol_id
    WHERE i.retirado_en IS NOT NULL AND de.retirado_en IS NULL;
END;
GO

CREATE TRIGGER mod05.trg_ref_ambiente_id_incidencias
ON mod05.incidencias
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (
        SELECT 1 FROM inserted i
        WHERE i.ambiente_id IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM mod03.ambiente d WHERE d.id_ambiente = i.ambiente_id))
    BEGIN
        ROLLBACK TRANSACTION;
        THROW 23503, N'Violación de referencia: ambiente_id inexistente en mod03.ambiente', 1;
    END
