CREATE FUNCTION mod09.fn_fecha_limite_correccion
(
    @desde DATE = NULL,
    @dias  INT  = NULL
)
RETURNS DATE
AS
BEGIN
    DECLARE @d DATE = DATEADD(DAY, 1, ISNULL(@desde, CAST(GETDATE() AS DATE)));
    DECLARE @limite INT = ISNULL(@dias, 15);
    DECLARE @contados INT = 0;

    WHILE @contados < @limite AND DATEDIFF(DAY, ISNULL(@desde, CAST(GETDATE() AS DATE)), @d) < 61
    BEGIN
        IF DATEDIFF(DAY, 0, @d) % 7 < 5
           AND NOT EXISTS (SELECT 1 FROM mod09.feriados WHERE fecha = @d)
            SET @contados = @contados + 1;

        IF @contados < @limite
            SET @d = DATEADD(DAY, 1, @d);
    END
    RETURN @d;
END;
GO


CREATE VIEW core.v_conexiones_en_vivo
AS
SELECT TOP 100 PERCENT
    s.session_id AS pid,
    s.login_name AS usuario_db,
    CAST(c.client_net_address AS NVARCHAR(45)) AS ip_origen,
    s.program_name AS cliente_app,
    s.login_time AS conexion_iniciada,
    s.status AS estado,
    t.[text] AS ultima_consulta_ejecutada,
    r.start_time AS hora_consulta
FROM sys.dm_exec_sessions s
LEFT JOIN sys.dm_exec_connections c ON c.session_id = s.session_id
LEFT JOIN sys.dm_exec_requests r ON r.session_id = s.session_id
OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t
WHERE s.database_id = DB_ID() AND s.session_id <> @@SPID
ORDER BY hora_consulta DESC;
GO

CREATE VIEW core.v_telemetria_equipos
AS
SELECT
    s.name AS esquema,
    CASE s.name
        WHEN 'core' THEN N'Equipo 01: Core: Arquitectura Central & SSO'
        WHEN 'mod01' THEN N'Equipo 02: Equipo 01: Matricula & Admision (Ismael)'
        WHEN 'mod02' THEN N'Equipo 03: Equipo 02: Asistencia & DPI (Sheyla)'
        WHEN 'mod03' THEN N'Equipo 04: Equipo 03: Inventario & Equipos (Brenda)'
        WHEN 'mod04' THEN N'Equipo 05: Equipo 04: Modulo 04 (Morales)'
        WHEN 'mod05' THEN N'Equipo 06: Equipo 05: Incidencias TI (Oliva)'
        WHEN 'mod06' THEN N'Equipo 07: Equipo 06: Egresados & Titulacion (Sandra/Max)'
        WHEN 'mod07' THEN N'Equipo 08: Equipo 07: Calidad Docente & Encuestas (Brayan)'
        WHEN 'mod08' THEN N'Equipo 09: Equipo 08: Roles & Seguridad Extendida (Toro)'
        WHEN 'mod09' THEN N'Equipo 10: Equipo 09: Tesoreria & Pagos TUPA (Vargas/Ismael)'
        ELSE s.name
    END AS equipo_asignado,
    COUNT(t.object_id) AS total_tablas,
    COALESCE(SUM(CASE WHEN p.index_id IN (0, 1) THEN p.row_count ELSE 0 END), 0) AS registros_actuales,
    0 AS total_inserts_historicos,
    0 AS total_updates_historicos,
    0 AS total_deletes_historicos,
    CAST(COALESCE(SUM(CAST(p.reserved_page_count AS BIGINT)), 0) * 8 AS NVARCHAR(50)) + ' KB' AS peso_en_disco,
    CASE
        WHEN COALESCE(SUM(CASE WHEN p.index_id IN (0, 1) THEN p.row_count ELSE 0 END), 0) > 50 THEN N'ALTA ACTIVIDAD'
        WHEN COALESCE(SUM(CASE WHEN p.index_id IN (0, 1) THEN p.row_count ELSE 0 END), 0) > 0 THEN N'ACTIVIDAD INICIAL'
        ELSE N'SIN ACTIVIDAD REGISTRADA'
    END AS semaforo_avance
FROM sys.tables t
JOIN sys.schemas s ON s.schema_id = t.schema_id
LEFT JOIN sys.dm_db_partition_stats p ON p.object_id = t.object_id
WHERE s.name IN ('core', 'mod01', 'mod02', 'mod03', 'mod04', 'mod05', 'mod06', 'mod07', 'mod08', 'mod09')
GROUP BY s.name;
GO

CREATE VIEW core.v_telemetria_tablas_detalle
AS
SELECT
    s.name AS esquema,
    t.name AS tabla,
    COALESCE(SUM(CASE WHEN p.index_id IN (0, 1) THEN p.row_count ELSE 0 END), 0) AS filas_estimadas,
    0 AS inserciones,
    0 AS modificaciones,
    0 AS eliminaciones,
    CAST(COALESCE(SUM(CAST(p.reserved_page_count AS BIGINT)), 0) * 8 AS NVARCHAR(50)) + ' KB' AS tamano_tabla,
    0 AS lecturas_completas,
    0 AS lecturas_por_indice
FROM sys.tables t
JOIN sys.schemas s ON s.schema_id = t.schema_id
LEFT JOIN sys.dm_db_partition_stats p ON p.object_id = t.object_id
WHERE s.name IN ('core', 'mod01', 'mod02', 'mod03', 'mod04', 'mod05', 'mod06', 'mod07', 'mod08', 'mod09')
GROUP BY s.name, t.name;
GO

CREATE VIEW mod02.v_resumen_asistencia_estudiante
AS
WITH calculohoras AS (
    SELECT
        a.estudiante_id,
        s.unidad_didactica_id,
        s.periodo_id,
        ud.nombre AS unidad_didactica_nombre,
        ud.codigo AS unidad_didactica_codigo,
        c.nombre AS carrera_nombre,
        e.ciclo_actual AS ciclo,
        e.turno,
        (ud.horas_semanales * 17) AS total_horas_semestre_regulares,
        (ud.horas_semanales * 18) AS total_horas_semestre_total,
        SUM(CASE WHEN a.estado = 'PRESENTE' THEN 1 ELSE 0 END) AS cant_presentes,
        SUM(CASE WHEN a.estado = 'TARDANZA' THEN 1 ELSE 0 END) AS cant_tardanzas,
        SUM(CASE WHEN a.estado = 'FALTA_JUSTIFICADA' THEN 1 ELSE 0 END) AS cant_faltas_justificadas,
        SUM(CASE WHEN a.estado = 'FALTA_INJUSTIFICADA' THEN 1 ELSE 0 END) AS cant_faltas_injustificadas,
        SUM(CASE WHEN a.estado = 'FALTA_INJUSTIFICADA' THEN s.horas_pedagogicas ELSE 0 END) AS horas_falta_injustificada,
        SUM(CASE WHEN a.estado = 'PRESENTE' THEN s.horas_pedagogicas ELSE 0 END) AS horas_asistidas,
        COUNT(a.id) AS total_sesiones_registradas
    FROM mod02.asistencias a
    JOIN mod02.sesiones_clase s ON s.id = a.sesion_clase_id
    JOIN core.unidades_didacticas ud ON ud.id = s.unidad_didactica_id
    JOIN core.estudiantes e ON e.id = a.estudiante_id
    JOIN core.carreras c ON c.id = e.carrera_id
    GROUP BY a.estudiante_id, s.unidad_didactica_id, s.periodo_id,
             ud.nombre, ud.codigo, ud.horas_semanales, c.nombre, e.ciclo_actual, e.turno
)
SELECT
    estudiante_id,
    unidad_didactica_id,
    periodo_id,
    unidad_didactica_nombre,
    unidad_didactica_codigo,
    carrera_nombre,
    ciclo,
    turno,
    total_horas_semestre_total AS total_horas_semestre,
    cant_presentes,
    cant_tardanzas,
    cant_faltas_justificadas,
    cant_faltas_injustificadas,
    horas_falta_injustificada,
    horas_asistidas,
    total_sesiones_registradas,
    ROUND(CASE WHEN total_horas_semestre_total = 0 THEN 0
               ELSE (CAST(horas_falta_injustificada AS DECIMAL(10,2)) * 100.0)
                    / total_horas_semestre_total END, 2) AS porcentaje_inasistencia,
    CASE
        WHEN CASE WHEN total_horas_semestre_total = 0 THEN 0
                  ELSE CAST(horas_falta_injustificada AS DECIMAL(10,2))
                       / total_horas_semestre_total END >= 0.30 THEN 'DPI'
        WHEN CASE WHEN total_horas_semestre_total = 0 THEN 0
                  ELSE CAST(horas_falta_injustificada AS DECIMAL(10,2))
                       / total_horas_semestre_total END >= 0.20 THEN 'RIESGO_ALTO'
        WHEN CASE WHEN total_horas_semestre_total = 0 THEN 0
                  ELSE CAST(horas_falta_injustificada AS DECIMAL(10,2))
                       / total_horas_semestre_total END >= 0.10 THEN 'ALERTA'
        ELSE 'REGULAR'
    END AS semaforo_estado,
    CASE WHEN (FLOOR(CAST(total_horas_semestre_total AS DECIMAL(10,2)) * 0.299)
               - CAST(horas_falta_injustificada AS DECIMAL(10,2))) < 0 THEN 0
         ELSE (FLOOR(CAST(total_horas_semestre_total AS DECIMAL(10,2)) * 0.299)
               - CAST(horas_falta_injustificada AS DECIMAL(10,2)))
    END AS horas_falta_disponibles
FROM calculohoras;
GO

CREATE VIEW mod03.v_inventario
AS
SELECT
    b.id_bien, b.cbi, b.codigo_inventario, b.descripcion,
    cb.nombre AS clasificacion, b.marca, b.modelo, b.serie, b.procedencia,
    b.fecha_ingreso, b.estado,
    a.nombre AS almacen_actual, a.ubicacion AS ubicacion_almacen,
    amb.nombre AS ambiente_actual, asg.responsable, b.observacion
FROM mod03.bien b
JOIN mod03.almacen a ON a.id_almacen = b.id_almacen
JOIN mod03.clasificaciones_bien cb ON cb.id_clasificacion = b.id_clasificacion
OUTER APPLY (
    SELECT TOP 1 ax.responsable, ax.id_ambiente
    FROM mod03.asignacion ax
    WHERE ax.id_bien = b.id_bien AND ax.estado = 'Activa'
    ORDER BY ax.fecha_asignacion DESC, ax.id_asignacion DESC
) AS asg
LEFT JOIN mod03.ambiente amb ON amb.id_ambiente = asg.id_ambiente;
GO

CREATE VIEW mod03.v_inventario_anual
AS
SELECT
    ia.id_inventario, ia.anio, ia.fecha_verificacion, ia.resultado,
    b.cbi, b.descripcion, b.serie,
    a.nombre AS almacen_actual, ia.observacion
FROM mod03.inventario_anual ia
JOIN mod03.bien b ON b.id_bien = ia.id_bien
JOIN mod03.almacen a ON a.id_almacen = b.id_almacen;
GO

CREATE VIEW mod03.v_transferencias
AS
SELECT
    t.id_transferencia, b.cbi, b.descripcion,
    ao.nombre AS almacen_origen, ad.nombre AS almacen_destino,
    t.fecha_solicitud, t.fecha_salida, t.fecha_recepcion,
    t.estado_movimiento, t.motivo,
    t.responsable_origen, t.responsable_destino, t.documento, t.observacion
FROM mod03.transferencia t
JOIN mod03.bien b ON b.id_bien = t.id_bien
JOIN mod03.almacen ao ON ao.id_almacen = t.id_almacen_origen
JOIN mod03.almacen ad ON ad.id_almacen = t.id_almacen_destino;
GO

CREATE VIEW mod05.v_citas_psicologia
AS
SELECT
    ct.id AS cita_id, ct.inicio, ct.fin, ct.estado, ct.origen,
    ct.nombres, ct.apellidos, ct.email, ct.motivo, ct.persona_id,
    p.dni, est.codigo_estudiante, ca.nombre AS carrera, ct.psicologo_id,
    CONCAT(pp.nombres, ' ', pp.apellidos) AS psicologo_nombre,
    ap.id AS atencion_id, ap.estado_atencion
FROM mod05.citas_psicologia ct
LEFT JOIN core.personas p ON p.id = ct.persona_id
LEFT JOIN core.estudiantes est ON est.persona_id = ct.persona_id
LEFT JOIN core.carreras ca ON ca.id = est.carrera_id
LEFT JOIN core.usuarios up ON up.id = ct.psicologo_id
LEFT JOIN core.personas pp ON pp.id = up.persona_id
LEFT JOIN mod05.atenciones_psicologia ap ON ap.cita_id = ct.id;
GO

CREATE VIEW mod05.v_incidencias_detalle
AS
SELECT
    i.id AS incidencia_id, i.reporte_id, i.fecha_registro, i.fecha_cierre,
    i.estado, i.dictamen, i.gravedad, i.tipo_falla, i.descripcion,
    i.solucion_aplicada, i.bien_id, b.cbi, b.codigo_inventario,
    b.descripcion AS bien_descripcion, b.marca, b.modelo, b.serie,
    cb.nombre AS tipo_bien, b.estado AS bien_estado_actual,
    i.estado_bien_previo, i.ambiente_id, am.nombre AS ambiente,
    e.nombre AS especialidad, i.aula_id, a.codigo AS aula, a.pabellon,
    i.carrera_id, c.nombre AS carrera, i.unidad_didactica_id, ud.nombre AS curso,
    i.docente_id, CONCAT(pd.nombres, ' ', pd.apellidos) AS docente_nombre,
    i.registrada_por, CONCAT(pr.nombres, ' ', pr.apellidos) AS registrada_por_nombre,
    i.tecnico_id, CONCAT(pt.nombres, ' ', pt.apellidos) AS tecnico_nombre
FROM mod05.incidencias i
LEFT JOIN mod03.bien b ON b.id_bien = i.bien_id
LEFT JOIN mod03.clasificaciones_bien cb ON cb.id_clasificacion = b.id_clasificacion
LEFT JOIN mod03.ambiente am ON am.id_ambiente = i.ambiente_id
LEFT JOIN mod03.especialidad e ON e.id_especialidad = am.id_especialidad
LEFT JOIN core.aulas a ON a.id = i.aula_id
LEFT JOIN core.carreras c ON c.id = i.carrera_id
LEFT JOIN core.unidades_didacticas ud ON ud.id = i.unidad_didactica_id
LEFT JOIN core.docentes d ON d.id = i.docente_id
LEFT JOIN core.personas pd ON pd.id = d.persona_id
LEFT JOIN core.usuarios ur ON ur.id = i.registrada_por
LEFT JOIN core.personas pr ON pr.id = ur.persona_id
LEFT JOIN core.usuarios ut ON ut.id = i.tecnico_id
LEFT JOIN core.personas pt ON pt.id = ut.persona_id;
GO

CREATE VIEW mod05.v_reportes_incidencia_detalle
AS
SELECT
    r.id AS reporte_id, r.fecha_reporte, r.estado, r.urgencia,
    r.tipo_falla, r.descripcion, r.reportado_por,
    CONCAT(pu.nombres, ' ', pu.apellidos) AS reportado_por_nombre,
    r.docente_id, d.codigo_docente,
    CONCAT(pd.nombres, ' ', pd.apellidos) AS docente_nombre,
    r.aula_id, a.codigo AS aula, a.pabellon,
    r.carrera_id, c.nombre AS carrera,
    r.unidad_didactica_id, ud.nombre AS curso,
    r.periodo_id, pa.codigo AS periodo,
    r.clase_docente_id, r.bien_id, b.cbi, b.codigo_inventario,
    b.descripcion AS bien_descripcion, b.estado AS bien_estado,
    r.equipo_descripcion, i.id AS incidencia_id
FROM mod05.reportes_incidencia r
JOIN core.usuarios u ON u.id = r.reportado_por
JOIN core.personas pu ON pu.id = u.persona_id
LEFT JOIN core.docentes d ON d.id = r.docente_id
LEFT JOIN core.personas pd ON pd.id = d.persona_id
LEFT JOIN core.aulas a ON a.id = r.aula_id
LEFT JOIN core.carreras c ON c.id = r.carrera_id
LEFT JOIN core.unidades_didacticas ud ON ud.id = r.unidad_didactica_id
LEFT JOIN core.periodos_academicos pa ON pa.id = r.periodo_id
LEFT JOIN mod03.bien b ON b.id_bien = r.bien_id
LEFT JOIN mod05.incidencias i ON i.reporte_id = r.id;
GO

CREATE VIEW mod05.v_requerimientos_detalle
AS
SELECT
    q.id AS requerimiento_id, q.fecha_solicitud, q.fecha_atencion,
    q.estado, q.prioridad, q.tipo_servicio, q.descripcion,
    q.observacion_resolucion, q.solicitante_id,
    CONCAT(ps.nombres, ' ', ps.apellidos) AS solicitante_nombre,
    q.tecnico_id, CONCAT(pt.nombres, ' ', pt.apellidos) AS tecnico_nombre,
    q.ambiente_id, am.nombre AS ambiente, q.aula_id, a.codigo AS aula,
    q.carrera_id, c.nombre AS carrera
FROM mod05.requerimientos q
JOIN core.usuarios us ON us.id = q.solicitante_id
JOIN core.personas ps ON ps.id = us.persona_id
LEFT JOIN core.usuarios ut ON ut.id = q.tecnico_id
LEFT JOIN core.personas pt ON pt.id = ut.persona_id
LEFT JOIN mod03.ambiente am ON am.id_ambiente = q.ambiente_id
LEFT JOIN core.aulas a ON a.id = q.aula_id
LEFT JOIN core.carreras c ON c.id = q.carrera_id;
GO

CREATE VIEW mod08.v_cubrimiento_roles
AS
SELECT
    r.id AS rol_id,
    r.nombre AS rol,
    COUNT(CASE WHEN u.estado = 1 THEN 1 END) AS usuarios_activos,
    COUNT(CASE WHEN u.estado = 0 THEN 1 END) AS usuarios_inactivos
FROM core.roles r
LEFT JOIN core.usuario_roles ur ON r.id = ur.rol_id AND ur.es_activo = 1
LEFT JOIN core.usuarios u ON ur.usuario_id = u.id
GROUP BY r.id, r.nombre;
GO

CREATE VIEW mod08.v_estado_acceso
AS
SELECT
    u.id AS usuario_id,
    p.dni,
    CONCAT(p.nombres, ' ', p.apellidos) AS nombre,
    u.ultimo_acceso,
    CASE WHEN u.estado = 1 THEN 0 ELSE 1 END AS bloqueado,
    (SELECT MAX(il.fecha) FROM mod08.intentos_login il
      WHERE il.usuario_id = u.id AND il.exito = 1) AS ultimo_login_exitoso,
    CASE WHEN EXISTS (SELECT 1 FROM mod08.identidades_externas ie
                       WHERE ie.usuario_id = u.id AND ie.desvinculado_en IS NULL)
         THEN 1 ELSE 0 END AS tiene_google,
    CASE WHEN (
        SELECT COUNT(*) FROM mod08.intentos_login f
         WHERE f.usuario_id = u.id
           AND f.exito = 0
           AND f.proveedor = 'DNI_LOCAL'
           AND f.fecha > DATEADD(MINUTE,
               -ISNULL((SELECT TOP 1 pa.minutos_bloqueo FROM mod08.politicas_acceso pa ORDER BY pa.id DESC), 15), GETDATE())
           AND f.fecha > COALESCE((SELECT MAX(s.fecha) FROM mod08.intentos_login s
              WHERE s.usuario_id = u.id AND s.exito = 1 AND s.proveedor = 'DNI_LOCAL'), '1900-01-01'))
        >= ISNULL((SELECT TOP 1 pa.max_intentos_fallidos FROM mod08.politicas_acceso pa ORDER BY pa.id DESC), 3)
        THEN 1 ELSE 0 END AS bloqueado_temporal,
    CASE WHEN u.password_hash LIKE '$2[aby]$%' THEN 1 ELSE 0 END AS tiene_password
FROM core.usuarios u
JOIN core.personas p ON u.persona_id = p.id;
GO

CREATE VIEW mod08.v_usuarios_roles
AS
SELECT
    u.id AS usuario_id, p.dni,
    CONCAT(p.nombres, ' ', p.apellidos) AS nombre,
    u.codigo_institucional, u.email, u.estado, r.nombre AS rol
FROM core.usuarios u
JOIN core.personas p ON u.persona_id = p.id
JOIN core.usuario_roles ur ON u.id = ur.usuario_id
JOIN core.roles r ON ur.rol_id = r.id
WHERE ur.es_activo = 1;
GO

